-- ============================================================================
-- Cetking Universe — VERBAL MASTER TAXONOMY
-- Prepared 15 Oct 2026. DO NOT RUN until Ravneet says "create the taxonomy table".
--
-- Shape MIRRORS the live public.quant_master_taxonomy so both sections share one
-- schema and can be queried or unioned together (Rav's 15 Oct rule: ONE master
-- taxonomy per section, one Cetking-wide ID system). Verbal-only columns are
-- grouped at the end: the G Strategy family, the RC/Non-RC tag, the White Book
-- chapter, the CAT PYQ count and the exam applicability.
--
-- Differences from Quant, by design:
--   * Verbal has NO topic level. Quant is section > subsection > chapter > topic
--     > core type; Verbal is section > subsection > chapter > core type. The
--     topic_* columns are kept for schema parity and left NULL.
--   * arena_questions is NULL — Verbal's Arena counts are not mapped yet.
--   * playbook_* are NULL — no Verbal playbooks written yet.
--
-- Additive only: nothing here touches an existing table, view or row.
-- Control Room steps (schema control_room) are built in: step 1 registers the
-- session and change request, step 4 records the handover.
-- ============================================================================

begin;

-- ─── STEP 1 · Control Room: register session + change request ───────────────
insert into control_room.sessions (actor, agent_type, purpose, status, notes)
values ('claude', 'opus', 'Create public.verbal_master_taxonomy (additive) and load 143 rows from the 15 Oct Verbal merge',
        'active', 'Verbal master taxonomy — merge of verbal-bible, question_taxonomy, taxonomy_universe_nodes, ck_topic_hierarchy, Arena map, cat_verbal_pyq_questions (506) and cat_import_questions (747 actual CAT Verbal). Shape mirrors quant_master_taxonomy. File of truth: reference-bank/verbal/master-taxonomy.csv in CetkingLearning/questions-universe.');

insert into control_room.change_requests (session_id, title, rationale, affected_objects, proposed_action, status, risk_level, rollback_notes)
select s.id,
  'Verbal master taxonomy: new table public.verbal_master_taxonomy + 143 rows',
  'Rav rule 15 Oct 2026: one master taxonomy per section, an ID at every level, everything in the Universe revolves around it. Quant done; this is Verbal, same schema.',
  array['public.verbal_master_taxonomy','public.verbal_master_taxonomy_chapters'],
  'CREATE TABLE + CREATE VIEW + INSERT 143 rows. No existing object altered. No row in any other table touched.',
  'in_progress', 'low',
  'drop view public.verbal_master_taxonomy_chapters; drop table public.verbal_master_taxonomy;'
from control_room.sessions s where s.actor='claude' and s.status='active'
order by s.started_at desc limit 1;

-- ─── STEP 2 · the table ─────────────────────────────────────────────────────
create table if not exists public.verbal_master_taxonomy (
  -- ── identity, same as quant_master_taxonomy ──
  master_id                 text primary key,     -- V · V-PG · V-PG-JUM · V-PG-JUM-001
  level                     text not null check (level in ('section','subsection','chapter','core_type')),
  parent_id                 text references public.verbal_master_taxonomy(master_id),
  name                      text not null,        -- the name at this level
  section_id                text not null default 'V',
  subsection_id             text,
  subsection_name           text,
  chapter_id                text,
  chapter_name              text,
  chapter_code              text,                 -- the 3-letter code, e.g. JUM
  cat_export_chapter        text,                 -- file under cat-universe/verbal/
  topic_id                  text,                 -- Verbal has no topic level: always NULL
  topic_no                  integer,
  topic_name                text,
  topic_aliases             text,
  core_type_id              text,
  core_type_no              integer,
  core_type_name            text,
  old_core_type_id          text,
  bible_core_id_provisional text,                 -- Verbal Bible reference, e.g. 'RC2 Tone', 'V6 6A'
  sort_order                integer,
  -- ── evidence flags, same as quant_master_taxonomy ──
  in_bible                  boolean default false,
  in_question_taxonomy      boolean default false,
  in_universe_nodes         boolean default false,
  in_arena                  boolean default false,
  arena_questions           integer,              -- not mapped for Verbal yet
  cat_questions_in_chapter  integer,
  match_status              text check (match_status in ('exact','synonym','bible_only','placeholder','batch','new')),
  proposed_addition         boolean default false,
  source_detail             text,
  playbook_rule             text,
  playbook_killer_move      text,
  notes                     text,
  status                    text not null default 'from_bible_unfrozen',
  approved_at               timestamptz,
  approved_by               text,
  source                    text not null default 'verbal_merge_15oct2026',
  created_at                timestamptz default now(),
  updated_at                timestamptz default now(),
  -- ── Verbal-only ──
  mother_core_type          text,                 -- G Strategy family: Summary / Paragraph / Evidence / Critical Reasoning
  rc_non                    text check (rc_non in ('RC','Non RC') or rc_non is null),
  white_book_chapter        text,
  cat_pyq_in_core_type      integer,              -- rows in cat_verbal_pyq_questions (506)
  exams                     text,                 -- CAT / CET / NMAT / CMAT? / SNAP? / XAT?
  exams_basis               text,
  rav_decision              text,
  rav_notes                 text
);

comment on table public.verbal_master_taxonomy is
  'THE master Verbal taxonomy for all of Cetking Universe (Rav, 15 Oct 2026). Same schema as quant_master_taxonomy. Every Verbal question, test, mock, handout, book and page revolves around this. Rows stay from_bible_unfrozen until Rav freezes a chapter. The V- master_id is an ADDITIONAL key: taxonomy_universe_nodes.taxonomy_code, question_taxonomy.id and ck_topic_hierarchy.id keep their own foreign keys. Verbal has no topic level, so topic_* are always NULL.';

create index if not exists verbal_master_taxonomy_level_idx      on public.verbal_master_taxonomy(level);
create index if not exists verbal_master_taxonomy_parent_idx     on public.verbal_master_taxonomy(parent_id);
create index if not exists verbal_master_taxonomy_subsection_idx on public.verbal_master_taxonomy(subsection_id);
create index if not exists verbal_master_taxonomy_chapter_idx    on public.verbal_master_taxonomy(chapter_id);
create index if not exists verbal_master_taxonomy_mother_idx     on public.verbal_master_taxonomy(mother_core_type);

alter table public.verbal_master_taxonomy enable row level security;
drop policy if exists verbal_master_taxonomy_read on public.verbal_master_taxonomy;
create policy verbal_master_taxonomy_read on public.verbal_master_taxonomy for select using (true);
-- writes: service role only (no insert/update/delete policy), like the other content tables.

-- ─── STEP 3 · the 144 rows (parents before children) ────────────────────────

-- section (1)
insert into public.verbal_master_taxonomy (master_id, level, parent_id, name, section_id, subsection_id, subsection_name, chapter_id, chapter_name, chapter_code, cat_export_chapter, core_type_id, core_type_no, core_type_name, bible_core_id_provisional, sort_order, in_bible, in_question_taxonomy, in_universe_nodes, in_arena, cat_questions_in_chapter, match_status, proposed_addition, source_detail, notes, mother_core_type, rc_non, white_book_chapter, cat_pyq_in_core_type, exams, exams_basis) values
  ('V', 'section', NULL, 'Verbal', 'V', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, true, true, true, true, 747, 'exact', false, 'Verbal section across all sources', NULL, NULL, NULL, NULL, 506, 'CAT · CET · NMAT · CMAT? · SNAP? · XAT?', 'Verbal appears in every MBA entrance paper; the mix of types differs')
on conflict (master_id) do nothing;

