-- ─── chapter roll-up view (mirrors quant_master_taxonomy_chapters) ──────────
create or replace view public.verbal_master_taxonomy_chapters as
select c.master_id                as chapter_id,
       c.subsection_name,
       c.chapter_name,
       c.chapter_code,
       c.mother_core_type,
       c.white_book_chapter,
       c.cat_export_chapter,
       c.cat_questions_in_chapter,
       c.cat_pyq_in_core_type     as cat_pyq_in_chapter,
       c.exams,
       count(t.master_id)                                        as core_types,
       count(t.master_id) filter (where t.match_status = 'exact') as core_types_live,
       count(t.master_id) filter (where t.proposed_addition)      as core_types_proposed,
       c.status,
       c.sort_order
from public.verbal_master_taxonomy c
left join public.verbal_master_taxonomy t on t.parent_id = c.master_id and t.level = 'core_type'
where c.level = 'chapter'
group by c.master_id, c.subsection_name, c.chapter_name, c.chapter_code, c.mother_core_type,
         c.white_book_chapter, c.cat_export_chapter, c.cat_questions_in_chapter,
         c.cat_pyq_in_core_type, c.exams, c.status, c.sort_order
order by c.sort_order;

-- ─── STEP 4 · verify, then Control Room handover ────────────────────────────
-- Expected: 1 section · 8 subsections · 41 chapters · 93 core types = 143 rows.
do $$
declare n integer; c integer;
begin
  select count(*) into n from public.verbal_master_taxonomy;
  select count(*) into c from public.verbal_master_taxonomy where level='core_type';
  if n <> 143 or c <> 93 then
    raise exception 'Verbal master taxonomy load wrong: % rows (expected 143), % core types (expected 93)', n, c;
  end if;
  select count(*) into n from public.verbal_master_taxonomy x
    where x.parent_id is not null
      and not exists (select 1 from public.verbal_master_taxonomy p where p.master_id = x.parent_id);
  if n > 0 then raise exception 'Verbal master taxonomy: % orphan rows', n; end if;
  select count(*) into n from public.verbal_master_taxonomy where level='core_type' and core_type_id is null;
  if n > 0 then raise exception 'Verbal master taxonomy: % core types without a core_type_id', n; end if;
end $$;

insert into control_room.change_events (request_id, session_id, actor, event_kind, object_schema, object_name, operation, details)
select cr.id, cr.session_id, 'claude', 'schema_and_data', 'public', 'verbal_master_taxonomy', 'CREATE+INSERT',
  'Created table + view verbal_master_taxonomy_chapters, schema mirroring quant_master_taxonomy. Loaded 143 rows (1 section, 8 subsections, 41 chapters, 93 core types). Verified counts, parent integrity and core_type_id in-transaction. All rows status=from_bible_unfrozen; 23 core types proposed_addition. No existing object or row changed. Outstanding: (1) 424 actual-CAT RC rows have no question_type — 248 can be tagged from cat_verbal_pyq_questions, see reference-bank/verbal/TAGGING-PLAN.md; (2) 68 answer rows need Rav (33 mismatch, 21 missing_found, 12 not_found, 2 not_checked); (3) CAT 2024 Verbal has ZERO RC rows; (4) CAT 2025 has 186 rows for 100 unique; (5) 12 of the 20 Verbal G Strategy names are absent from cat_card_map, so 18 actual-CAT questions cannot reach a Shabda card; (6) 4 Arena mappings still pending; (7) 10 open decisions in reference-bank/verbal/summary.md. Next: Rav freezes chapters, then backfill cat_import_questions.ck_subsection/ck_chapter from this table.'
from control_room.change_requests cr
where cr.title = 'Verbal master taxonomy: new table public.verbal_master_taxonomy + 143 rows'
order by cr.created_at desc limit 1;

update control_room.change_requests
   set status='completed', completed_at=now(),
       verification_notes='143 rows, 93 core types, no orphans, every core type has a core_type_id — asserted inside the transaction.'
 where title = 'Verbal master taxonomy: new table public.verbal_master_taxonomy + 143 rows';

update control_room.sessions
   set status='finished', finished_at=now(), last_seen_at=now(),
       notes = coalesce(notes,'') || ' | Done: verbal_master_taxonomy created and loaded.'
 where actor='claude' and status='active';

commit;

-- ─── rollback, if ever needed ───────────────────────────────────────────────
-- drop view if exists public.verbal_master_taxonomy_chapters;
-- drop table if exists public.verbal_master_taxonomy;
